import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.ptr = gsl_matrix_alloc(rows, cols)
        if not self.ptr:
            raise MemoryError("Failed to allocate GSL matrix")
        self.rows = rows
        self.cols = cols

    def __del__(self):
        if hasattr(self, 'ptr') and self.ptr:
            gsl_matrix_free(self.ptr)

def gsl_matrix_alloc(rows, cols):
    func = gsl.gsl_matrix_alloc
    func.argtypes = [ctypes.c_size_t, ctypes.c_size_t]
    func.restype = ctypes.c_void_p
    return func(rows, cols)

def gsl_matrix_free(matrix_ptr):
    func = gsl.gsl_matrix_free
    func.argtypes = [ctypes.c_void_p]
    func(matrix_ptr)

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_mat = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            value = np_array[i, j]
            gsl.gsl_matrix_set(gsl_mat.ptr, i, j, value)
    return gsl_mat

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.rows
    cols = gsl_matrix.cols
    np_array = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            value = gsl.gsl_matrix_get(gsl_matrix.ptr, i, j)
            np_array[i, j] = value
    return np_array

def gsl_multifit_covar(jacobian, epsrel):
    rows, cols = jacobian.shape
    covar = GSLMatrix(cols, cols)
    jac_gsl = numpy_to_gsl_matrix(jacobian)
    func = gsl.gsl_multifit_covar
    func.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]
    func(jac_gsl.ptr, epsrel, covar.ptr)
    return gsl_matrix_to_numpy(covar)

