def symmetric_rank2_update(order, uplo, N, alpha, X, incX, Y, incY, A, lda):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    if len(X) < (N - 1) * abs(incX) + 1:
        raise ValueError("X vector too short for given N and incX")
    if len(Y) < (N - 1) * abs(incY) + 1:
        raise ValueError("Y vector too short for given N and incY")
    if len(A) < lda * N:
        raise ValueError("A matrix too small for given lda and N")

    c_float_p = ctypes.POINTER(ctypes.c_float)

    cblas.cblas_ssyr2.restype = None
    cblas.cblas_ssyr2.argtypes = [
        ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_float,
        c_float_p, ctypes.c_int, c_float_p, ctypes.c_int, c_float_p, ctypes.c_int
    ]

    X_arr = (ctypes.c_float * len(X))(*X)
    Y_arr = (ctypes.c_float * len(Y))(*Y)
    A_arr = (ctypes.c_float * len(A))(*A)

    cblas.cblas_ssyr2(
        order, uplo, N, ctypes.c_float(alpha),
        X_arr, incX, Y_arr, incY, A_arr, lda
    )

    return list(A_arr)

