def allocate_rng(rng_name):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

    gsl.gsl_rng_alloc.restype = ctypes.c_void_p
    gsl.gsl_rng_alloc.argtypes = [ctypes.c_void_p]

    gsl.gsl_rng_env_setup.restype = None
    gsl.gsl_rng_env_setup()

    rng_type_ptr = gsl.gsl_rng_types_setup()
    if not rng_type_ptr:
        raise RuntimeError("Failed to get GSL RNG types")

    class gsl_rng_type(ctypes.Structure):
        _fields_ = [
            ("name", ctypes.c_char_p),
            ("max", ctypes.c_ulong),
            ("min", ctypes.c_ulong),
            ("size", ctypes.c_size_t),
            ("set", ctypes.c_void_p),
            ("get", ctypes.c_void_p),
            ("get_double", ctypes.c_void_p)
        ]

    class gsl_rng(ctypes.Structure):
        _fields_ = [
            ("type", ctypes.POINTER(gsl_rng_type)),
            ("state", ctypes.c_void_p)
        ]

    current_type = ctypes.cast(rng_type_ptr, ctypes.POINTER(ctypes.POINTER(gsl_rng_type)))
    found_type = None

    while current_type.contents:
        type_name = current_type.contents.contents.name.decode('utf-8')
        if type_name == rng_name:
            found_type = current_type.contents
            break
        current_type = ctypes.cast(ctypes.addressof(current_type.contents) + ctypes.sizeof(ctypes.c_void_p), ctypes.POINTER(ctypes.POINTER(gsl_rng_type)))

    if not found_type:
        raise ValueError(f"Unknown RNG type: {rng_name}")

    rng_ptr = gsl.gsl_rng_alloc(found_type)
    if not rng_ptr:
        raise RuntimeError("Failed to allocate RNG")

    return ctypes.cast(rng_ptr, ctypes.POINTER(gsl_rng))

