class GSLPolyComplexWorkspace:
    def __init__(self, n):
        self.ptr = gsl.gsl_poly_complex_workspace_alloc(n)
        if not self.ptr:
            raise MemoryError("Failed to allocate GSL polynomial complex workspace")

    def __del__(self):
        if hasattr(self, 'ptr') and self.ptr:
            gsl.gsl_poly_complex_workspace_free(self.ptr)

def compute_complex_roots(coefficients):
    if not all(isinstance(c, (float, int)) for c in coefficients):
        raise TypeError("All coefficients must be floating-point numbers")

    n = len(coefficients) - 1
    if n < 1:
        raise ValueError("Polynomial must have degree at least 1")

    workspace = GSLPolyComplexWorkspace(n + 1)

    coeffs_array = (ctypes.c_double * len(coefficients))(*coefficients)
    z_array = (ctypes.c_double * (2 * n))()

    result = gsl.gsl_poly_complex_solve(coeffs_array, len(coefficients), workspace.ptr, z_array)

    if result != 0:
        raise RuntimeError(f"GSL polynomial solver failed with error code {result}")

    roots = []
    for i in range(n):
        real_part = z_array[2*i]
        imag_part = z_array[2*i+1]
        roots.append(complex(real_part, imag_part))

    return roots

