    def _create_gsl_matrix(self):
        gsl_matrix = ctypes.POINTER(ctypes.c_double * self.size * self.size)()
        for i in range(self.size):
            for j in range(self.size):
                self.gsl_matrix[i][j] = ctypes.c_double(self.data[i][j])
        return gsl_matrix

    def to_list(self):
        result = []
        for i in range(self.size):
